using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "FissionExpertiseEffect", menuName = "Data/Battle/Effects/Orion/FissionExpertise Effect")]
public class FissionExpertiseEffect : Effect
{
	[Header("FissionExpertise Effect")]
	[SerializeField]
	private Effect effect;

	public override string GetEffectDescription(int amount, GameObject effectOwner = null)
	{
		string localizedThenDecreaseEffect = base.localizationManager.GetLocalizedThenDecreaseEffect(effect, 1);
		string text = "";
		text = ((amount != EffectsValues.NO_VALUE && amount != -1) ? Smart.Format(GetLocalizedDescription(), amount, localizedThenDecreaseEffect) : GetEffectDescriptionWithAmountReplacedWithX(GetLocalizedDescription(), GetNumberToReplaceWithX(), localizedThenDecreaseEffect));
		return text + AppendedDescription();
	}
}
